];

/**
 * @description Reset the Zigbee2mqtt integration to a clean factory state.
 * @example
 * await this.reset();
 */
async function reset() {
  logger.info('Zigbee2mqtt: resetting integration...');

  // Stop & remove both MQTT and zigbee2mqtt containers
  await this.disconnect();

  // Destroy all configuration variables
  await Promise.all(
    CONFIGURATION_VARIABLES.map((key) => this.gladys.variable.destroy(key, this.serviceId)),
  );

  // Delete the zigbee2mqtt data folder
  const { basePathOnContainer } = await this.gladys.system.getGladysBasePath();
  await fs.rm(path.join(basePathOnContainer, 'zigbee2mqtt'), { recursive: true, force: true });

  // Reset in-memory state
  this.discoveredDevices = {};
  this.topicBinds = {};
  this.usbConfigured = false;
  this.mqttExist = false;
  this.mqttRunning = false;
  this.mqttContainerRunning = false;
  this.zigbee2mqttExist = false;
  this.zigbee2mqttRunning = false;
  this.gladysConnected = false;
  this.zigbee2mqttConnected = false;
  this.z2mPermitJoin = false;
  this.coordinatorFirmware = null;
  this.z2mContainerError = null;

  this.emitStatusEvent();

  // Disconnect from MQTT broker
  if (this.mqttClient) {
    this.mqttClient.end();
    this.mqttClient.removeAllListeners();
    this.mqttClient = null;
  }

  // Stop backup recurrent job
  if (this.backupScheduledJob) {
    this.backupScheduledJob.cancel();
  }
}

module.exports = {
  reset,
};
